# Extract the review texts (the "Instance" parts)
import re

reviews = []
lines = context.strip().split('\n')
for line in lines:
    if '|| Instance:' in line:
        # Extract the instance text
        match = re.search(r'\|\| Instance: (.+)$', line)
        if match:
            reviews.append(match.group(1))

print(f"Found {len(reviews)} reviews:")
for i, r in enumerate(reviews, 1):
    print(f"{i}. {r[:80]}...")
